record() { if [ "$2" -eq "$3" ]; then echo "PASS $1 (rc=$2)"; pass=$((pass+1)); else echo "FAIL $1 (rc=$2 want=$3)"; fail=$((fail+1)); fi; }
expect_txt() { if printf '%s\n' "$2" | grep -F -- "$3" >/dev/null; then echo "PASS $1"; pass=$((pass+1)); else echo "FAIL $1"; fail=$((fail+1)); fi; }
reject_txt() { if printf '%s\n' "$2" | grep -F -- "$3" >/dev/null; then echo "FAIL $1"; fail=$((fail+1)); else echo "PASS $1"; pass=$((pass+1)); fi; }
# Fixtures run from $scratch; cases that KILL a helper orphan its children, so reap by path before removing it.
reap_scratch() { local re n=0 left; re=$(printf '%s' "$scratch/" | sed 's/[][\.*^$+?(){}|]/\\&/g'); left=$(pgrep -f "$re" || true); while [ -n "$left" ] && [ "$n" -lt 40 ]; do kill -KILL $left 2>/dev/null || true; sleep 0.05; left=$(pgrep -f "$re" || true); n=$((n+1)); done; [ -z "$left" ] || { echo "FAIL fixture processes survived reap: $left" >&2; exit 1; }; }
scratch=$(mktemp -d); trap 'reap_scratch; rm -rf "$scratch"' EXIT; mkdir -p "$scratch/bin" "$scratch/rt" "$scratch/static" "$scratch/install"
write_bin() { printf '%s\n' "$2" > "$scratch/bin/$1"; chmod +x "$scratch/bin/$1"; }
up_coop='  *fake-upstream.mjs) echo $$ > "$RUNNER_TEMP/upstream.pid"; printf "%s\n" "{\"port\":${FAKE_UPSTREAM_PORT:-19016}}"; trap "exit 0" TERM; while true; do sleep 0.05; done ;;'
write_node() { printf '%s\n' '#!/bin/sh' 'case "$1" in' "$up_coop" 'esac' 'echo $$ > "$RUNNER_TEMP/node.pid"' "$@" > "$scratch/bin/node"; chmod +x "$scratch/bin/node"; }
term_node() { write_node "trap \"exit $1\" TERM" 'while true; do sleep 0.05; done'; }
ok_curl() { write_bin curl $'#!/bin/sh\nif printf "%s" " $* " | grep -F "chat/completions" >/dev/null; then echo 401; exit 0; fi\nexit 0'; }
ok_make() { write_bin make $'#!/bin/sh\n[ "$1" = "$EXPECT_TARGET" ] || exit 9\necho fake make ok; exit 0'; }
alive_pid() { [ -f "$1" ] && kill -0 "$(cat "$1")" 2>/dev/null; }; pid_of() { [ -f "$1" ] && cat "$1" || true; }
assert_dead() { if alive_pid "$1"; then echo "FAIL $2"; fail=$((fail+1)); kill -KILL "$(cat "$1")" 2>/dev/null || true; else echo "PASS $2"; pass=$((pass+1)); fi; }
reap_pids() { for p in "$@"; do [ -n "${p:-}" ] && kill -KILL "$p" 2>/dev/null || true; k=0; while [ -n "${p:-}" ] && [ "$k" -lt 40 ] && kill -0 "$p" 2>/dev/null; do sleep 0.05; k=$((k+1)); done; done; }
ck_sent() { if kill -0 "$1" 2>/dev/null; then echo "PASS $2"; pass=$((pass+1)); kill -TERM "$1" 2>/dev/null || true; wait "$1" 2>/dev/null || true; else echo "FAIL $2"; fail=$((fail+1)); fi; }
with_h() { PATH="$scratch/bin:/usr/bin:/bin" RUNNER_TEMP="$scratch/rt" HOST=127.0.0.1 PORT=18016 SMOKE_BASE_URL=http://127.0.0.1:18016 UI_WALK_BASE_URL=http://127.0.0.1:18016 DB_PATH="$scratch/rt/app.db" STATIC_ROOT="$scratch/static" OMP_BIN="$scratch/bin/omp" OMP_STATE_DIR="$scratch/rt/omp-state" SANDBOX_ROOT="$scratch/rt/sandbox" MODEL_UPSTREAM_BASE_URL=http://127.0.0.1:19016/v1 MODEL_UPSTREAM_API_KEY=fake FAKE_UPSTREAM_PORT=19016 EXPECT_TARGET="${EXPECT_TARGET:-smoke}" CI_TERM_WAIT="${CI_TERM_WAIT:-2}" CI_KILL_WAIT="${CI_KILL_WAIT:-1}" CI_READY_SLEEP="${CI_READY_SLEEP:-0.05}" "$@"; }
run_helper() { EXPECT_TARGET="$1" with_h "$BASH_RUN" "${2:-$helper}" "$1"; }
waitf() { n=0; while [ "$n" -lt 80 ] && [ ! -f "$1" ]; do sleep 0.05; n=$((n+1)); done; [ -f "$1" ] || { echo "FAIL missing ${1##*/}"; fail=$((fail+1)); }; }; waitp() { n=0; while [ "$n" -lt 80 ] && kill -0 "$1" 2>/dev/null; do sleep 0.05; n=$((n+1)); done; }; bg() { with_h exec "$BASH_RUN" "$1" smoke >"$2" 2>&1 & wp=$!; }
ed() { python3 -c 'import sys;s=open(sys.argv[1]).read();p,n=sys.argv[3],sys.argv[4];sys.exit(2) if s.count(p)!=1 else open(sys.argv[5],"w").write(s.replace(p,n,1) if sys.argv[2]=="r" else s[:s.find(p)+len(p)]+"\n"+n+"\n"+s[s.find(p)+len(p):])' "$1" "$2" "$3" "$4" "$5" && chmod +x "$5"; }
inj() { ed "${4:-$helper}" i "$2" "$3" "$1" || { echo "FAIL inj $2"; fail=$((fail+1)); printf '%s\n' '#!/bin/sh' 'exit 2' > "$1"; chmod +x "$1"; }; }
mark() { inj "$1" 'ec=$?' ': > "$RUNNER_TEMP/cleanup.mark"'; }
bar() { inj "$1" 'on_exit() {' ': > "$RUNNER_TEMP/cleanup.mark"; while [ ! -f "$RUNNER_TEMP/cleanup.go" ]; do sleep 0.05; done' "${2-}"; }
