# Every duplicate starts from the current source; generation failure is not rejection.
owner_mut() { python3 - "$root/constraints.yaml" "$scratch/constraints.yaml" "$@" <<'PY'
import sys
source, dest, owner, quote, position, value = sys.argv[1:]
text = open(source).read()
anchor = "\n" + owner + ":\n"
if text.count(anchor) != 1 or position not in ("before", "after"):
    sys.exit(2)
body = ("  fast_checks_timeout_minutes: " + value + "\n  anti_drift_timeout_minutes: " + value + "\n"
        if owner == "ci" else "  surfaces: {}\n")
block = "\n" + quote + owner + quote + ":\n" + body
result = text.replace(anchor, block + anchor, 1) if position == "before" else text + block
open(dest, "w").write(result)
PY
}
owner_case() {
  local name="constraints $1 owner $2 $3 value=$4"
  if owner_mut "$@"; then
    if [ "$1" = ci ]; then
      if with_oracle "$wf" "$scratch/constraints.yaml"; then rc=0; else rc=$?; fi
    else
      ccopy; cp "$scratch/constraints.yaml" "$contract_copy/constraints.yaml"
      if contract "$contract_copy"; then rc=0; else rc=$?; fi
    fi
    record "$name" "$rc" 1
  else echo "FAIL $name missing anchor"; fail=$((fail+1)); fi
}
for quote in '"' "'"; do
  for position in before after; do
    for value in 5 10; do owner_case ci "$quote" "$position" "$value"; done
    owner_case verification "$quote" "$position" empty
  done
  expect_constraints "single ci owner $quote" 0 $'\nci:\n' $'\n'"${quote}ci${quote}:"$'\n'
  cm "single verification owner $quote" constraints.yaml $'\nverification:\n' $'\n'"${quote}verification${quote}:"$'\n' 0
done
