import re, sys
src, dest, mode, job, *rest = sys.argv[1:]
text = open(src).read()
anchor = "  " + job + ":\n"
start = text.find(anchor)
if start < 0:
    sys.exit(2)
more = re.search(r"\n  [^ ]", text[start + len(anchor):])
stop = len(text) if more is None else start + len(anchor) + more.start()
body = text[start:stop]
step_re = re.compile(r"(?m)^      - uses: ([^\n]+)\n((?: {8,}.*\n)*)")
def steps(action=None):
    found = []
    for match in step_re.finditer(body):
        used = match.group(1)
        if action is None or used.startswith(action + "@"):
            found.append(match)
    return found
def one(action):
    found = steps(action)
    if len(found) != 1:
        sys.exit(2)
    return found[0]
if mode == "ref":
    match = one(rest[0])
    body = body[:match.start(1)] + rest[0] + "@" + rest[1] + body[match.end(1):]
elif mode == "drop":
    match = one(rest[0])
    body = body[:match.start()] + body[match.end():]
elif mode == "dup":
    match = one(rest[0])
    body = body[:match.end()] + match.group(0) + body[match.end():]
elif mode == "replace":
    match = one(rest[0])
    body = body[:match.start(1)] + rest[1] + body[match.end(1):]
elif mode == "before":
    match = one(rest[0])
    body = body[:match.start()] + rest[1] + body[match.start():]
elif mode == "after-run":
    match = one(rest[0])
    step = match.group(0)
    body = body[:match.start()] + body[match.end():]
    needle = rest[1]
    if body.count(needle) != 1:
        sys.exit(2)
    idx = body.find(needle)
    nl = body.find("\n", idx)
    if nl < 0:
        sys.exit(2)
    body = body[:nl + 1] + step + body[nl + 1:]
elif mode == "sub":
    match = one(rest[0])
    chunk = match.group(0)
    if chunk.count(rest[1]) != 1:
        sys.exit(2)
    body = body[:match.start()] + chunk.replace(rest[1], rest[2], 1) + body[match.end():]
elif mode == "job-env":
    payload = "    env: { ACTIONS_ALLOW_USE_UNSECURE_NODE_VERSION: true }\n" if rest[0] == "inline" else "    env:\n      ACTIONS_ALLOW_USE_UNSECURE_NODE_VERSION: true\n"
    body = body[:len(anchor)] + payload + body[len(anchor):]
