def lex(spec):
    words, word, i = [], "", 0
    while i < len(spec):
        c = spec[i]
        if c == "\\" and i + 1 < len(spec):
            word += spec[i + 1] if spec[i + 1] in ":\\,= \t#" else spec[i:i + 2]
            i += 2
            continue
        if c in "#:,=":
            break
        if c in " \t":
            if word:
                words.append(word)
            word = ""
        else:
            word += c
        i += 1
    if word:
