uid_rule_mutant glued r '  printf '"'"'%s ALL=(omp) NOPASSWD: SETENV: /usr/bin/setpriv --pdeathsig KILL -- %s*\n'"'"' "$1" "$real_rule"' "zero trailing arguments allowed"
uid_rule_mutant widened i '  printf '"'"'%s ALL=(omp) NOPASSWD: SETENV: %s *\n'"'"' "$1" "$real_rule"' "command without launcher allowed"
if ed "$uid_helper" r '  sudo chmod 0440 /etc/sudoers.d/runner' '  true' "$scratch/uid-no-runner-mode.sh"; then
  rm -f "$scratch/rt/uid-sg.log"
  set +e; out=$(uid_run "$scratch/uid-no-runner-mode.sh" 2>&1); rc=$?; set -e
  record "hosted sudoers global visudo rejects missing normalization" "$rc" 9
  [ ! -f "$scratch/rt/uid-sg.log" ] && { echo "PASS global visudo blocked children"; pass=$((pass+1)); } || { echo "FAIL global visudo allowed children"; fail=$((fail+1)); }
else echo "FAIL hosted sudoers mode mutant missing anchor"; fail=$((fail+1)); fi
if ed "$uid_helper" r 'sudo setfacl -m u:omp:--x "$runner_home"' 'true' "$scratch/uid-no-acl.sh"; then
  rm -f "$scratch/rt/uid-sg.log" "$scratch/rt/uid-acl"
  set +e; out=$(uid_run "$scratch/uid-no-acl.sh" 2>&1); rc=$?; set -e
  record "missing runner home ACL fails before children" "$rc" 9
  [ ! -f "$scratch/rt/uid-sg.log" ] && { echo "PASS missing ACL blocked children"; pass=$((pass+1)); } || { echo "FAIL missing ACL allowed children"; fail=$((fail+1)); }
else echo "FAIL missing ACL mutant missing anchor"; fail=$((fail+1)); fi
for stage in preflight useradd copy permissions test smoke; do
  rm -f "$scratch/rt/uid-sg.log" "$scratch/rt/uid-test-seen"
  if [ "$stage" = preflight ]; then : > "$uid_state/proof home:colon/deny"; fi
  set +e; out=$(UID_FAIL="$stage" uid_run 2>&1); rc=$?; set -e
  [ "$stage" != preflight ] || rm -f "$uid_state/proof home:colon/deny"
  case "$stage" in test|smoke) [ -f "$scratch/rt/uid-sg.log" ] && { echo "PASS uid $stage reached group phase"; pass=$((pass+1)); } || { echo "FAIL uid $stage did not reach group phase"; fail=$((fail+1)); } ;;
    *) [ ! -f "$scratch/rt/uid-sg.log" ] && { echo "PASS uid $stage did not start child"; pass=$((pass+1)); } || { echo "FAIL uid $stage started child"; fail=$((fail+1)); } ;; esac
  case "$stage" in preflight|useradd|permissions) want=9 ;; copy|test|smoke) want=7 ;; esac
  record "uid $stage failure propagates" "$rc" "$want"
done
rm -f "$scratch/rt/uid-sg.log" "$scratch/rt/uid-kill.log"
: > "$scratch/rt/uid-owned"; sleep 30 & sentinel=$!
set +e; out=$(uid_run 2>&1); rc=$?; set -e
record "uid residue marks success failed" "$rc" 1
expect_txt "uid residue diagnostic" "$out" "omp uid residue after phase"
if grep -F '/bin/kill -TERM 424242' "$scratch/rt/uid-kill.log" >/dev/null && kill -0 "$sentinel" 2>/dev/null && [ "$(wc -l < "$scratch/rt/uid-sg.log")" -eq 1 ]; then
  echo "PASS uid reaps only owned stub and blocks smoke"; pass=$((pass+1))
else echo "FAIL uid residue ownership or phase"; fail=$((fail+1)); fi
kill -TERM "$sentinel" 2>/dev/null || true; wait "$sentinel" 2>/dev/null || true
rm -f "$scratch/rt/uid-sg.log" "$scratch/rt/uid-kill.log"
set +e; out=$(UID_FAIL=stubborn uid_run 2>&1); rc=$?; set -e
record "uid KILL escalation remains failure" "$rc" 1
expect_txt "uid KILL escalation diagnostic" "$out" "KILL escalation for omp uid residue"
if grep -F '/bin/kill -KILL 424242' "$scratch/rt/uid-kill.log" >/dev/null; then echo "PASS uid KILL targeted owned stub"; pass=$((pass+1)); else echo "FAIL uid KILL target"; fail=$((fail+1)); fi
rm -f "$scratch/rt/uid-sg.log"
set +e; out=$(UID_FAIL=inspect uid_run 2>&1); rc=$?; set -e
record "uid process inspection failure blocks smoke" "$rc" 1
expect_txt "uid inspection diagnostic" "$out" "cannot inspect omp uid processes"
[ "$(wc -l < "$scratch/rt/uid-sg.log")" -eq 1 ] && { echo "PASS uid inspection failed before smoke"; pass=$((pass+1)); } || { echo "FAIL uid inspection allowed smoke"; fail=$((fail+1)); }
rm -f "$scratch/rt/uid-sg.log" "$scratch/rt/uid-kill.log"
set +e; out=$(UID_FAIL=smoke-residue uid_run 2>&1); rc=$?; set -e
record "uid smoke primary failure survives owned residue cleanup" "$rc" 7
expect_txt "uid smoke residue reported" "$out" "omp uid residue after phase"
if grep -F '/bin/kill -TERM 424242' "$scratch/rt/uid-kill.log" >/dev/null && [ "$(wc -l < "$scratch/rt/uid-sg.log")" -eq 2 ]; then echo "PASS uid smoke residue owned cleanup"; pass=$((pass+1)); else echo "FAIL uid smoke residue cleanup"; fail=$((fail+1)); fi
uid_life() {
  local op="$1" phase="$2" want=1 extra desc leader hung=0 rc; [ "$phase" = smoke ] && want=2
  rm -f "$scratch/rt/uid-sg.log" "$scratch/rt/uid-"*.pid "$scratch/rt/uid-ready" "$scratch/rt/uid-release"; sleep 30 & sentinel=$!
  set +e; uid_bg; set -e; waitf "$scratch/rt/uid-ready"; extra=$(pid_of "$scratch/rt/uid-child.pid"); desc=$(pid_of "$scratch/rt/uid-desc.pid"); leader=$(pid_of "$scratch/rt/uid-sg.pid")
  [ -n "$extra" ] && [ -n "$desc" ] && [ -n "$leader" ] && [ "$extra" != "$desc" ] && [ "$extra" != "$leader" ] && [ "$desc" != "$leader" ] && [ "$wp" != "$extra" ] && [ "$wp" != "$desc" ] && [ "$wp" != "$leader" ] && kill -0 "$wp" 2>/dev/null && kill -0 "$extra" 2>/dev/null && kill -0 "$desc" 2>/dev/null && kill -0 "$leader" 2>/dev/null && [ "$(wc -l < "$scratch/rt/uid-sg.log")" -eq "$want" ] && [ "$(ps -o pgid= -p "$leader" | tr -d ' ')" = "$(ps -o pgid= -p "$desc" | tr -d ' ')" ] && [ "$(ps -o pgid= -p "$leader" | tr -d ' ')" = "$(ps -o pgid= -p "$extra" | tr -d ' ')" ] && hung=1
  if [ "$hung" != 1 ]; then echo "FAIL uid $phase $op never hung"; fail=$((fail+1)); extra=$(pid_of "$scratch/rt/uid-child.pid"); desc=$(pid_of "$scratch/rt/uid-desc.pid"); leader=$(pid_of "$scratch/rt/uid-sg.pid"); reap_pids "$desc" "$extra" "$leader" "$wp"; wait "$wp" 2>/dev/null || true; ck_sent "$sentinel" "uid $phase $op setup sentinel"; return; fi
  if [ "$op" = cancel ]; then kill -TERM "$wp" 2>/dev/null || true; else : > "$scratch/rt/uid-release"; fi; waitp "$wp"; if kill -0 "$wp" 2>/dev/null; then echo "FAIL uid $phase $op wrapper hung"; fail=$((fail+1)); extra=$(pid_of "$scratch/rt/uid-child.pid"); desc=$(pid_of "$scratch/rt/uid-desc.pid"); leader=$(pid_of "$scratch/rt/uid-sg.pid"); reap_pids "$desc" "$extra" "$leader" "$wp"; wait "$wp" 2>/dev/null || true; ck_sent "$sentinel" "uid $phase $op hung sentinel"; return; fi
  if wait "$wp"; then rc=0; else rc=$?; fi; record "uid $phase $op wrapper exit" "$rc" "$([ "$op" = cancel ] && echo 143 || echo 7)"; extra=$(pid_of "$scratch/rt/uid-child.pid"); desc=$(pid_of "$scratch/rt/uid-desc.pid"); leader=$(pid_of "$scratch/rt/uid-sg.pid"); [ "$op" = status ] && expect_txt "uid $phase leftover group diagnostic" "$(cat "$scratch/rt/uid-cancel.out")" "phase group still present after leader exit"
  for name in child:"$extra" descendant:"$desc" sg:"$leader"; do kill -0 "${name#*:}" 2>/dev/null && { echo "FAIL uid $phase $op left ${name%%:*}"; fail=$((fail+1)); } || { echo "PASS uid $phase $op reaped ${name%%:*}"; pass=$((pass+1)); }; done
  reap_pids "$desc" "$extra" "$leader" "$wp"; ck_sent "$sentinel" "uid $phase $op sentinel survived"
}
for op in cancel status; do for phase in test smoke; do UID_FAIL=$op-$phase uid_life "$op" "$phase"; done; done
echo "ci-harness oracle: $pass PASS / $fail FAIL"
[ "$fail" -eq 0 ]
